:root {
  --ink: #243334;
  --muted: #667778;
  --card: #fffdf7;
  --line: #dbe5dd;
  --sage: #dcebdd;
  --sage-ink: #356348;
  --sun: #f4b84a;
}

.checkin-card {
  width: 440px;
  box-sizing: border-box;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--card);
  color: var(--ink);
}

.checkin-card header {
  display: flex;
  align-items: center;
  gap: 11px;
}

.sun-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--sage);
  font-size: 22px;
}

.session-copy {
  flex: 1;
}

.session-copy h1 {
  margin: 0 0 2px;
  font-size: 18px;
  line-height: 1.15;
}

.session-copy p,
.details p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.4;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--sage);
  color: var(--sage-ink);
  font-size: 12px;
  font-weight: 700;
}

.details {
  display: flex;
  justify-content: space-between;
  margin: 16px 0;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.location {
  color: var(--sage-ink) !important;
}

.checkin-card button {
  width: 100%;
  padding: 10px;
  border: 0;
  border-radius: 9px;
  background: var(--sun);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  font-weight: 700;
}
